    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Background Image Display</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            height: 100vh; /* Ensure the body takes up full viewport */
            display: flex;
            justify-content: center;
            align-items: center;
            background-color: #f5f5f5;
        }
        .background-image-container {
            position: relative;
            width: 100%;
            height: 100%;
        }
        .overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.7); /* Semi-transparent black overlay for better visibility */
            z-index: 1;
        }
    </style>
</head>
<body>
    <!-- Button to toggle the background image -->
    <button id="toggle-button">Show Background Image</button>

    <!-- Container to hold the image and overlay -->
    <div class="background-image-container">
        <img id="background-image" src="" alt="Background Image" />
        <div class="overlay"></div>
    </div>

    <script>
        // Function to get the background image URL from the user's computer
        function getImageUrl() {
            const url = window.URL.createObjectURL(new Blob([document.body.style.backgroundImage]));
            return url;
        }

        document.getElementById('toggle-button').addEventListener('click', () => {
            const backgroundImageContainer = document.querySelector('.background-image-container');
            const overlay = document.querySelector('.overlay');

            if (backgroundImageContainer) {
                backgroundImageContainer.remove();
                overlay.remove();
            } else {
                const imgElement = document.createElement('img');
                imgElement.src = getImageUrl();
                imgElement.id = 'background-image';
                backgroundImageContainer.appendChild(imgElement);
                backgroundImageContainer.appendChild(overlay);
            }
        });
    </script>
</body>
</html>
```

